def check_custom_exception_inheritance(node):
    for class_def in node.get('body').get('body'):
        if isinstance(class_def, ast.ClassDef) and class_def.name and class_def.name.id not in ('BaseException', 'Exception'):
            if not class_def.bases or any(base.arg not in ('BaseException', 'Exception') for base in class_def.bases):
                return True
